/**
 * Banco de Exercícios de Kettlebell — base científica completa.
 *
 * 82 exercícios catalogados com:
 * - Padrão de movimento (HINGE / SQUAT / PRESS / PULL / CARRY / ROT / COND / FLOW)
 * - Cues técnicos (3-5 frases-chave)
 * - Errors comuns (2-4 armadilhas)
 * - Equipamento, nível, grupos musculares
 * - Vídeo demonstrativo (URL pública CDN)
 * - Imagem estática (URL pública CDN)
 * - Referências bibliográficas (PMID/DOI quando disponível)
 *
 * Origem dos dados: projeto "Caderno de Kettlebell v18" (https://9kpf9n4jnm7t1.space.minimax.io/)
 * Fontes principais: McGill 2012 (PMID 22201691), Lake & Lauder 2012, Bullington 2015 (PMC4637916),
 *                    BELL trial 2022 (PMC9026020), LIFTMOR 2018 (PMID 28929619), Refalo 2022 (PMID 36178597),
 *                    Schoenfeld 2017 (DOI 10.1080/02640414.2016.1210197), Khan 2024 (PMC11077891),
 *                    Tsatsouline 2019 (Simple & Sinister).
 *
 * Schema é backward-compatible com Exercicio (de exercicios.ts).
 */

import type { Exercicio } from './exercicios';

export type PadraoKettlebell = 'HINGE' | 'SQUAT' | 'PRESS' | 'PULL' | 'CARRY' | 'ROT' | 'COND' | 'FLOW';

/**
 * Galeria de imagens - uma imagem por etapa do exercício
 */
export interface ExerciseImageStep {
  /** URL pública da imagem (pode ser Wikimedia Commons, local, etc) */
  src: string;
  /** Texto alternativo para acessibilidade */
  alt: string;
  /** Legenda curta exibida abaixo */
  caption: string;
  /** Nome do arquivo no Wikimedia Commons (para referência) */
  source?: string;
}

/**
 * Etapas detalhadas do exercício (passo a passo)
 */
export interface ExerciseStep {
  /** Número da etapa (1-based) */
  numero: number;
  /** Título curto da etapa */
  titulo: string;
  /** Descrição detalhada do que fazer nesta etapa */
  descricao: string;
  /** Tempo aproximado nesta posição (segundos) */
  duracaoSeg?: number;
  /** Imagem correspondente (se disponível) */
  imagem?: ExerciseImageStep;
  /** Cues técnicos para esta etapa */
  cues?: string[];
  /** O que você deve SENTIR nesta etapa (linguagem leiga) */
  sensacoes?: string[];
  /** Sinais de ERRO muscular - pare se sentir */
  alertasMusculares?: string[];
}

export interface ExercicioKettlebell extends Exercicio {
  padraoKb: PadraoKettlebell;
  cues: string[];
  errors: string[];
  alerta50mais?: string;
  contraIndicacoes?: string[];
  evidencia?: string;
  referencias?: string[];
  videoUrl?: string;
  imageUrl?: string;
  thumbnailUrl?: string;
  /** Galeria de imagens (etapas múltiplas) */
  galleryImages?: ExerciseImageStep[];
  /** Etapas detalhadas com descrição, cues e imagem */
  steps?: ExerciseStep[];
  /** Origem/contexto adicional (e.g., Wikimedia file sources) */
  fontesExternas?: { name: string; url: string; license: string }[];
  /** Mapa muscular em linguagem leiga (Sprint 34) */
  mapaMuscularLeigo?: string[];
  /** Sensação principal que deve sentir (Sprint 34) */
  sensacaoPrincipal?: string;
  /** Erro muscular comum (Sprint 34) */
  erroMuscular?: string;
  /** Analogia inicial para iniciantes (Sprint 34) */
  analogiaInicial?: string;
  /** Carga inicial recomendada para 50+ (Sprint 34) */
  cargaInicial50mais?: string;
}

const CDN_BASE = '/kettlebell';

function img(name: string): string {
  return `${CDN_BASE}/images/${name}`;
}
function vid(name: string): string {
  return `${CDN_BASE}/videos/${name}`;
}

