    padraoKb: 'PULL',
    equipamento: 'kettlebell',
    nivel: 'avancado',
    focoPrincipal: 'Dorsal + tríceps + peito (multi-articular extremo)',
    musculosSecundarios: ['Core', 'Antebraço/grip', 'Deltóide', 'Bíceps'],
    descricao: 'Pull-up + DIP combinados em movimento único e contínuo. Variação com KB no quadril (em cinto ou short com argola). Requer pull-up FORTE + transição EXPLOSIVA + dip FORTE. Entre os exercícios mais difíceis.',
    dicas: ['False grip (pegada na transição)', 'Pull EXPLOSIVO (não controlado)', 'Transição com cotovelos sobre barra', 'KB no quadril para adicionar carga'],
    cues: ['Pull explosivo', 'Transition (cotovelos sobre)', 'Press (lockout)', 'Centro de gravidade no quadril'],
    errors: ['Transição incompleta (cotovelos não passam)', 'Pull fraco (não atinge altura)', 'KB oscilar (centro de gravidade perdido)', 'Flexão de quadril para compensar'],
    alerta50mais: '⚠️ AVANÇADO — só para atletas com pull-up sólido + dip sólido. Para 50+: NÃO recomendado. Use pull-up + dip em exercícios separados.',
    contraIndicacoes: ['Lesão no ombro (impacto)', 'Lombalgia crônica', 'Epicondilite / cotovelo de tenista', 'Capsulite adesiva', 'Sedentário (começar com pull-up)'],
    evidencia: 'Kippers & Richardson 2010: Muscle-Up requer produção de força > 100% do peso corporal na fase de pull (vs 60-70% em pull-up comum). KB no quadril pode adicionar 10-30 kg de carga externa, dificultando ainda mais.',
    imageUrl: undefined,
    videoUrl: undefined,
    mapaMuscularLeigo: [
      'GRANDE DORSAL (latíssimo) — pull (fase 1) — puxa corpo para cima',
      'PEITORAL — transição (fase 2) — puxa cotovelos sobre a barra',
      'TRÍCEPS — empurra (fase 3) — estende cotovelos para lockout',
      'BÍCEPS + BRAQUIAL — auxiliam no pull (flexão de cotovelo)',
      'DELTÓIDE POSTERIOR — pull (extensão horizontal)',
      'DELTÓIDE ANTERIOR — transição + press',
      'ROMBOIDE + TRAPÉZIO MÉDIO — estabilizam escápula',
      'MANGUITO ROTADOR — estabiliza articulação glenoumeral',
      'CORE (abdômen + oblíquo + lombar) — estabiliza tronco durante pendurado',
      'ERETORES DA ESPINHA — estabilizam coluna',
      'ANTEBRAÇO/GRIP — segura barra TODO o tempo',
      'GLÚTEO + ISQUIOTIBIAL — estabilizam quadril durante pendurado',
    ],
    sensacaoPrincipal: 'PULL EXPLOSIVO — sensação de voar para cima (impulso poderoso). TRANSIÇÃO — momento crítico onde cotovelos passam pela barra (peito trabalha). PRESS — empurrar até lockout (tríceps finaliza). KB no quadril ADICIONA DIFICULDADE — corpo TODO envolvido. CORE é o estabilizador invisível.',
    erroMuscular: 'Se NÃO COMPLETAR: pull fraco — treine pull-up + dip separados por 2-3 meses antes. Se LOMBAR DOER: core fraco OU KB pesado. Se OMBRO DOER: carga excessiva ou técnica ruim. Se GRIPE FALHAR: barra inadequada OU grip fraco — use magnésio. Se TRANSICÃO INCOMPLETA: precisa de mais impulso (pull mais explosivo).',
    analogiaInicial: 'Imagine um ginasta olímpico subindo em uma barra — primeiro puxa forte para passar o peito da barra, depois gira os cotovelos para passar por cima, e finalmente empurra para ficar com os braços estendidos. Tudo em UM movimento contínuo. KB no quadril é como se você estivesse puxando uma mochila pesada nas costas.',
