    erroMuscular: 'Se KB descer no catch (não fica overhead): DRIVE fraco — não está usando quadril, está tentando só com braço. CORREÇÃO: foque em pular com quadril, não em erguer KB. Se joelho DOER durante re-dip: profundidade excessiva — reduza a flexão (~15-20° em vez de 30°). Se oscilação do KB: estabilize o manguito rotador (aperte a mão no lockout).',
